fn zero_negatives(items: &mut Vec[Int]) {
  let i = 0;
  while i < items.len() {
    if items[i] < 0 { items[i] = 0; }
    i = i + 1;
  }
}

fn remove_evens(items: &mut Vec[Int]) {
  let i = 0;
  while i < items.len() {
    if items[i] % 2 == 0 {
      items[i] = items[items.len() - 1];
      items.pop();
    } else {
      i = i + 1;
    }
  }
}

fn main() -> Int {
  var data = Vec[Int].new();
  data.push(-5);
  data.push(10);
  data.push(-3);
  data.push(7);
  data.push(4);
  data.push(-1);
  zero_negatives(&mut data);
  remove_evens(&mut data);
  return data.len() as Int;
}
